        private string HtmlEncodeText(string strText)
        {
            if (strText == null || strText.Length == 0)
                return "&nbsp;";
            return strText.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;").Replace("\"", "&quot;");
        }

        private string GetDataRowText(DataRow drw, string strField)
        {
            if (drw == null || !drw.Table.Columns.Contains(strField) || drw[strField] == DBNull.Value)
                return "";
            return Convert.ToString(drw[strField]);
        }

        private string FormatSummaryMark(object objValue, string strFormat)
        {
            if (objValue == null || objValue == DBNull.Value)
                return "&nbsp;";

            string strRaw = Convert.ToString(objValue);
            if (strRaw.Length < 1)
                return "&nbsp;";
            if (strRaw == "-1")
                return "M";

            try
            {
                double dbl = Convert.ToDouble(objValue);
                System.Globalization.CultureInfo cul = new System.Globalization.CultureInfo("vi-VN");
                return dbl.ToString(strFormat, cul);
            }
            catch
            {
                return HtmlEncodeText(strRaw);
            }
        }

        private string FormatSigningDate(object objValue)
        {
            if (objValue == null || objValue == DBNull.Value)
                return "";
            try
            {
                DateTime dtm = Convert.ToDateTime(objValue);
                return dtm.ToString("dd/MM/yyyy");
            }
            catch
            {
                return Convert.ToString(objValue);
            }
        }

