        private string BuildSubjectColumnHtml(DataTable dtbSubjects, int intFrom, int intTo, int intStartSTT)
        {
            StringBuilder sb = new StringBuilder();
            sb.Append("<table class='subject-table'>");
            sb.Append("<thead>");
            sb.Append("<tr>");
            sb.Append("<th rowspan='2' style='width:28px'>TT</th>");
            sb.Append("<th rowspan='2'>Môn học</th>");
            sb.Append("<th rowspan='2' style='width:36px'>ĐV<br/>HT</th>");
            sb.Append("<th colspan='2'>Kết quả</th>");
            sb.Append("</tr><tr>");
            sb.Append("<th style='width:36px'>ĐL1</th>");
            sb.Append("<th style='width:36px'>ĐL2</th>");
            sb.Append("</tr></thead><tbody>");

            if (intTo > intFrom)
            {
                for (int i = intFrom; i < intTo; i++)
                {
                    DataRow drw = dtbSubjects.Rows[i];
                    sb.Append("<tr>");
                    sb.Append("<td>").Append((intStartSTT + (i - intFrom) + 1).ToString()).Append("</td>");
                    sb.Append("<td class='col-subject'>").Append(HtmlEncodeText(GetDataRowText(drw, "SubjectName"))).Append("</td>");
                    sb.Append("<td>").Append(HtmlEncodeText(GetDataRowText(drw, "UnitText"))).Append("</td>");
                    sb.Append("<td>").Append(FormatSummaryMark(drw.Table.Columns.Contains("Summary1") ? drw["Summary1"] : null, "0.0")).Append("</td>");
                    sb.Append("<td>").Append(FormatSummaryMark(drw.Table.Columns.Contains("Summary2") ? drw["Summary2"] : null, "0.0")).Append("</td>");
                    sb.Append("</tr>");
                }
            }

            sb.Append("</tbody></table>");
            return sb.ToString();
        }

        private string BuildSubjectTableHtml(DataTable dtbSubjects)
        {
            int intTotal = dtbSubjects.Rows.Count;
