            StringBuilder sb = new StringBuilder();
            sb.Append("<table class='subject-wrap'><tr>");
            sb.Append("<td style='width:50%'>");
            sb.Append(BuildSubjectColumnHtml(dtbSubjects, 0, intLeftCount, 0));
            sb.Append("</td>");
            sb.Append("<td style='width:50%'>");
            sb.Append(BuildSubjectColumnHtml(dtbSubjects, intLeftCount, intTotal, intLeftCount));
            sb.Append("</td>");
            sb.Append("</tr></table>");
            return sb.ToString();
        }

