        private string LoadHtmlTemplate(string strRelativePath, string strFallbackTitle)
        {
            string[] arrPaths = new string[] {
                Application.StartupPath + "\\" + strRelativePath,
                Application.StartupPath + "\\..\\..\\" + strRelativePath,
                Application.StartupPath + "\\..\\..\\..\\" + strRelativePath
            };

            for (int i = 0; i < arrPaths.Length; i++)
            {
                try
                {
                    string strFull = System.IO.Path.GetFullPath(arrPaths[i]);
                    if (System.IO.File.Exists(strFull))
                        return System.IO.File.ReadAllText(strFull, Encoding.UTF8);
                }
                catch
                {
                }
            }

            StringBuilder sb = new StringBuilder();
            sb.Append("<!DOCTYPE html><html><head><meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />");
            sb.Append("<title>").Append(strFallbackTitle).Append("</title>");
            sb.Append("<style type=\"text/css\">body{font-family:'Times New Roman',Times,serif;font-size:11pt;margin:12px;}</style>");
            sb.Append("</head><body>{CONTENT}</body></html>");
            return sb.ToString();
        }

        private void SaveAndOpenHtml(string strFileName, string strContent)
        {
            string strExportDir = Application.StartupPath + "\\Export";
            if (!System.IO.Directory.Exists(strExportDir))
                System.IO.Directory.CreateDirectory(strExportDir);

            string strFilePath = strExportDir + "\\" + strFileName;
            System.IO.File.WriteAllText(strFilePath, strContent, Encoding.UTF8);
            System.Diagnostics.Process.Start(strFilePath);
        }

        /// <summary>
        /// Xuất HTML - Bảng điểm học tập và tốt nghiệp (cấu trúc giống Leaning_BangDiemTotNghiep).
        /// Dữ liệu truyền y như report cũ: SearchStudentMarkSummary + SearchSubject_Graduation1.
        /// </summary>
        private void ExportBangDiemHocTapTotNghiep_HTML()
        {
            try
            {
                SIM_Student objStudentMarkSummary = new SIM_Student();
                SIM_Class_Subject objClassSubject = new SIM_Class_Subject();

                foreach (int i in gvData.GetSelectedRows())
                {
                    DataRow drw = gvData.GetDataRow(i);
                    DataTable dtbStudentMarkSummary = objStudentMarkSummary
                        .SearchStudentMarkSummary(Convert.ToInt64(drw[SIM_Student.C_StudentID]));
                    DataTable dtbClassSubject = objClassSubject
                        .SearchSubject_Graduation1(Convert.ToInt64(drw[SIM_Student.C_StudentID]));

                    if (dtbStudentMarkSummary == null || dtbStudentMarkSummary.Rows.Count == 0)
                    {
                        ErrorManager.Error("Việc lấy thông tin sinh viên bị lỗi!");
                        continue;
                    }

                    DataRow drwInfo = dtbStudentMarkSummary.Rows[0];

                    DateTime dtmNow = SystemService.SYS_SettingService.CurrentDateTime;
                    string strPlace = SystemService.SYS_SettingService.GetStringValue("Report_Place");
                    if (strPlace == null)
                        strPlace = "";
                    string strPlaceDate = strPlace
                        + ", ngày " + dtmNow.Day.ToString()
                        + " tháng " + dtmNow.Month.ToString()
                        + " năm " + dtmNow.Year.ToString();

                    StringBuilder sb = new StringBuilder();
                    sb.Append("<div class='print-page'>");
                    sb.Append(BuildHtmlHeaderBlock());
                    sb.Append("<div class='place-date'>").Append(HtmlEncodeText(strPlaceDate)).Append("</div>");
                    sb.Append("<div class='title'>KẾT QUẢ HỌC TẬP VÀ TỐT NGHIỆP</div>");
                    sb.Append(BuildStudentInfoHtml(drwInfo));
                    sb.Append(BuildSubjectTableHtml(dtbStudentMarkSummary));
                    sb.Append(BuildGraduationFooterHtml(drwInfo, dtbClassSubject));
                    sb.Append(BuildSignatureHtml());
                    sb.Append("</div>");

                    string strTemplate = LoadHtmlTemplate("MauHtml\\BangDiem\\BangDiem_HocTapTotNghiep.htm", "Bảng điểm học tập và tốt nghiệp");
                    string strFileContent = strTemplate.Replace("{CONTENT}", sb.ToString());

                    string strStudentCode = GetDataRowText(drwInfo, "StudentCode");
                    if (strStudentCode == null || strStudentCode.Length < 1)
                        strStudentCode = Convert.ToString(drw[SIM_Student.C_StudentID]);
                    strStudentCode = strStudentCode.Replace("\\", "_").Replace("/", "_").Replace(":", "_");

                    SaveAndOpenHtml(strStudentCode + "_BangDiem_HocTapTotNghiep.htm", strFileContent);
                }
            }
            catch
            {
                ErrorManager.Error("Dữ liệu chưa hợp lệ để xuất HTML!");
            }
        }

        #endregion Xuất HTML - Bảng điểm học tập và tốt nghiệp
    }
